      de:{crumb:'Sicherheit',title:'Bedingungen für die Ausführung geschützter Handler.',lead:"Bestehende Clients → HTTPS/TLS → FastAPI → Gateway → ODRE v3 → Core → Protected Handler. Der API-Vertrag der Clients bleibt erhalten. ODRE v3 läuft zwischen Gateway und Core, nicht zwischen Mobilgeräten und Server.",verificationCta:'Release & Verifikation',documentsCta:'Sicherheitsdokumente',architectureTitle:'Sicherheitsarchitektur',cryptoTitle:'Kryptografische Rollen',hybridTitle:'Hybrider Handshake',failTitle:'Fail closed ohne stilles Classical-only-Downgrade.',threatTitle:'Bedrohungsgrenze und Einschränkungen',releaseTitle:'Release & Verifikation',current:'Aktuelles verifiziertes Release',runtime:'Kryptografische Runtime',wheel:'Offizielles Wheel',hashTitle:'Wheel SHA-256',whitepaper:'Technisches Whitepaper'},
