    payment:{ko:{crumb:'결제 도움말',title:'결제와 라이선스 전달 도움말.',lead:'결제를 이미 완료했다면 다시 구매하지 마세요. 라이선스 이메일이 늦으면 복구 페이지 또는 라이선스 지원을 이용하세요.',plans:'요금제와 결제',recovery:'라이선스 이메일 복구',support:'라이선스 지원'},ja:{crumb:'決済ヘルプ',title:'決済とライセンス送付のヘルプ。',plans:'プランと決済',recovery:'ライセンスメール復旧',support:'ライセンスサポート'},de:{crumb:'Zahlungshilfe',title:'Hilfe zu Zahlung und Lizenzzustellung.',plans:'Pläne und Checkout',recovery:'Lizenzmail wiederherstellen',support:'Lizenz-Support'},es:{crumb:'Ayuda de pago',title:'Ayuda con pago y entrega de licencia.',plans:'Planes y checkout',recovery:'Recuperar correo de licencia',support:'Soporte de licencias'}},
    paymentSuccess:{ko:{activate:'라이선스 활성화',activationHelp:'다음 단계는 라이선스 활성화입니다. 결제 이메일로 받은 License ID와 License Key를 준비해 주세요.',crumb:'주문 확인',received:'결제 접수',title:'주문을 확인하고 있습니다.',lead:'결제와 결제 이메일을 독립적으로 확인합니다. 확인이 완료되면 결제에 사용한 이메일로 라이선스 정보를 보냅니다.',notice:'다시 결제하지 마세요. 이 브라우저 복귀 페이지 자체는 결제 증명이 아니며 라이선스 발급 완료를 의미하지 않습니다.',recover:'라이선스 이메일을 못 받으셨나요?',plans:'라이선스 요금제로 돌아가기'},ja:{activate:'ライセンスを有効化',activationHelp:'次はライセンスの有効化です。決済メールに届いた License ID と License Key をご用意ください。',crumb:'注文確認',received:'決済受付',title:'注文を確認しています。',lead:'決済とメールを独立して確認し、確認後にライセンス情報を送付します。',notice:'再度支払わないでください。このページだけでは決済証明や発行完了になりません。',recover:'ライセンスメールが届きませんか？',plans:'ライセンスプランへ'},de:{activate:'Lizenz aktivieren',activationHelp:'Aktivieren Sie als Nächstes Ihre Lizenz. Halten Sie License ID und License Key aus Ihrer Zahlungs-E-Mail bereit.',crumb:'Bestellbestätigung',received:'Zahlung eingegangen',title:'Wir bestätigen Ihre Bestellung.',lead:'Zahlung und Checkout-E-Mail werden unabhängig geprüft. Danach werden Lizenzinformationen an diese E-Mail gesendet.',notice:'Nicht erneut bezahlen. Diese Rückkehrseite allein ist kein Zahlungsnachweis und bestätigt keine Lizenzausgabe.',recover:'Lizenzmail nicht erhalten?',plans:'Zurück zu Lizenzplänen'},es:{activate:'Activar licencia',activationHelp:'El siguiente paso es activar su licencia. Prepare el License ID y la License Key enviados a su correo de pago.',crumb:'Confirmación',received:'Pago recibido',title:'Estamos confirmando su pedido.',lead:'El pago y el correo se verifican de forma independiente. Después se envía la información de licencia.',notice:'No vuelva a pagar. Esta página por sí sola no prueba el pago ni confirma una licencia emitida.',recover:'¿No recibió el correo?',plans:'Volver a planes'}}
